def _close_eyes(im):
    """闭眼：把头部中段的眼睛(亮/饱和像素)替换为肤色，营造闭眼(避开顶部天线)。"""
    im = im.copy()
    px = im.load(); w, h = im.size
    from collections import Counter
    cnt = Counter()
    y0, y1 = int(h * 0.22), int(h * 0.50)
    for y in range(y0, y1):
        for x in range(w):
            r, g, b, a = px[x, y]
            if a < 200:
                continue
            mx, mn = max(r, g, b), min(r, g, b)
            if mx - mn > 60:            # 跳过眼睛/装饰，采样肤色
                continue
            cnt[(r // 16, g // 16, b // 16)] += 1
    if not cnt:
        return im
    sk = cnt.most_common(1)[0][0]
    skin = (sk[0] * 16 + 8, sk[1] * 16 + 8, sk[2] * 16 + 8)
    for y in range(y0, y1):
        for x in range(w):
            r, g, b, a = px[x, y]
            if a < 200:
                continue
            mx, mn = max(r, g, b), min(r, g, b)
            if mx - mn > 60 and mx > 110:   # 饱和 + 较亮 = 眼睛
                px[x, y] = (skin[0], skin[1], skin[2], 255)
    return im


